CREATE OR REPLACE FUNCTION pkg_claim_admin.get_status_label ( p_status claim.claim_status%TYPE ) RETURNS varchar AS $body$
BEGIN
        CASE p_status
            WHEN 'NEW' THEN
                RETURN 'Pending Intake';

            WHEN 'PROCESSING' THEN
                RETURN 'Under Review';

            WHEN 'PAID' THEN
                RETURN 'Completed';

            WHEN 'DENIED' THEN
                RETURN 'Rejected';

            ELSE
                RETURN 'Unknown';
        END CASE;
    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
