CREATE OR REPLACE PROCEDURE pkg_claim_admin.upsert_audit ( p_process_name migration_audit.process_name%TYPE, p_source_count migration_audit.source_count%TYPE, p_target_count migration_audit.target_count%TYPE, p_status migration_audit.status%TYPE, p_message migration_audit.message%TYPE ) AS $body$
BEGIN

        MERGE INTO migration_audit a
        USING(
            SELECT p_process_name process_name

        ) s
        ON (
            a.process_name = s.process_name
            AND date_trunc('day', a.created_timestamp) = date_trunc('day', clock_timestamp())
        )

        WHEN MATCHED THEN
            UPDATE SET
                a.source_count      = p_source_count,
                a.target_count      = p_target_count,
                a.status            = p_status,
                a.message           = p_message,
                a.created_timestamp = statement_timestamp()

        WHEN NOT MATCHED THEN
            INSERT(
                audit_id,
                process_name,
                source_count,
                target_count,
                status,
                message,
                created_timestamp
            )
            VALUES (
                nextval('seq_migration_audit'),
                p_process_name,
                p_source_count,
                p_target_count,
                p_status,
                p_message,
                statement_timestamp()
            );

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE pkg_claim_admin.upsert_audit ( p_process_name migration_audit.process_name%TYPE, p_source_count migration_audit.source_count%TYPE, p_target_count migration_audit.target_count%TYPE, p_status migration_audit.status%TYPE, p_message migration_audit.message%TYPE ) FROM PUBLIC;



CREATE OR REPLACE PROCEDURE pkg_claim_admin.recalculate_open_claims () AS $body$
DECLARE

        c_claims CURSOR FOR
            SELECT claim_id
            FROM claim
            WHERE claim_status IN ('NEW','PROCESSING');

        l_count numeric := 0;


BEGIN

        FOR r IN c_claims LOOP

            CALL pr_recalculate_claim(r.claim_id);

            l_count := l_count + 1;

        END LOOP;

        CALL pkg_claim_admin.upsert_audit(
            'RECALCULATE_OPEN_CLAIMS',
            l_count,
            l_count,
            'SUCCESS',
            'Open claims processed successfully'
        );

    EXCEPTION
        WHEN OTHERS THEN

            CALL pkg_claim_admin.upsert_audit(
                'RECALCULATE_OPEN_CLAIMS',
                l_count,
                0,
                'FAILED',
                SUBSTR(SQLERRM,1,4000)
            );

            RAISE;

    END;
$body$
LANGUAGE PLPGSQL
SECURITY DEFINER
;
-- REVOKE ALL ON PROCEDURE pkg_claim_admin.recalculate_open_claims () FROM PUBLIC;
